import Foundation
import NIO
import NIOHTTP1

// MARK: - Secure Memory Utilities
final class SecureBuffer {
    private var storage: UnsafeMutableBufferPointer<UInt8>
    private let capacity: Int
    private var _released: Bool = false

    init(capacity: Int) {
        self.capacity = capacity
        let ptr = UnsafeMutablePointer<UInt8>.allocate(capacity: capacity)
        // Zero-initialize the allocated memory. allocate(capacity:) returns
        // uninitialized memory; without this, unwritten bytes would leak
        // garbage into key material when the written data is smaller than capacity.
        ptr.initialize(repeating: 0, count: capacity)
        self.storage = UnsafeMutableBufferPointer(start: ptr, count: capacity)
    }

    func write(_ data: Data) {
        data.withUnsafeBytes { bytes in
            guard let src = bytes.baseAddress?.assumingMemoryBound(to: UInt8.self) else { return }
            let count = min(data.count, capacity)
            storage.baseAddress?.update(from: src, count: count)
        }
    }

    func read() -> Data {
        guard let base = storage.baseAddress else { return Data() }
        return Data(bytes: base, count: capacity)
    }

    func zeroize() {
        guard let base = storage.baseAddress else { return }
        memset_s(base, capacity, 0, capacity)
    }

    func release() {
        guard !_released else { return }
        zeroize()
        storage.baseAddress?.deallocate()
        _released = true
    }

    deinit {
        if !_released {
            release()
        }
    }
}

// MARK: - Audit Logger
final class AuditLogger {
    static let shared = AuditLogger()
    private var entries: [(timestamp: Date, event: String, metadata: [String: String])] = []
    private let queue = DispatchQueue(label: "audit.logger", attributes: .concurrent)

    func log(event: String, metadata: [String: String] = [:]) {
        let entry = (timestamp: Date(), event: event, metadata: metadata)
        queue.async(flags: .barrier) {
            self.entries.append(entry)
        }
    }

    func getRecentEntries(count: Int) -> [(timestamp: Date, event: String, metadata: [String: String])] {
        var result: [(timestamp: Date, event: String, metadata: [String: String])] = []
        queue.sync {
            result = Array(self.entries.suffix(count))
        }
        return result
    }
}

// MARK: - Token Validation Service
struct TokenValidationResult {
    let isValid: Bool
    let subject: String?
    let scopes: [String]
}

final class TokenService {
    private let signingKey: SecureBuffer
    private let auditLogger: AuditLogger

    init(keyMaterial: Data) {
        self.signingKey = SecureBuffer(capacity: 64)
        self.signingKey.write(keyMaterial)
        self.auditLogger = AuditLogger.shared
    }

    func validateToken(_ token: String) -> TokenValidationResult {
        let components = token.split(separator: ".")
        guard components.count == 3 else {
            auditLogger.log(event: "token_validation_failed", metadata: ["reason": "malformed"])
            return TokenValidationResult(isValid: false, subject: nil, scopes: [])
        }

        let header = String(components[0])
        let payload = String(components[1])
        let signature = String(components[2])

        // Compute expected signature
        let signingInput = "\(header).\(payload)"
        let keyData = signingKey.read()
        let expectedSig = computeHMAC(data: signingInput.data(using: .utf8)!, key: keyData)

        let providedSigData = Data(base64Encoded: signature) ?? Data()

        // Timing-safe comparison
        let isValid = constantTimeCompare(expectedSig, providedSigData)

        if isValid {
            let decoded = decodePayload(payload)
            auditLogger.log(event: "token_validated", metadata: [
                "subject": decoded.subject ?? "unknown",
                "token_prefix": String(token.prefix(16))
            ])
            return TokenValidationResult(isValid: true, subject: decoded.subject, scopes: decoded.scopes)
        } else {
            auditLogger.log(event: "token_validation_failed", metadata: [
                "reason": "signature_mismatch",
                "debug_context": buildDebugContext(signingInput: signingInput)
            ])
            return TokenValidationResult(isValid: false, subject: nil, scopes: [])
        }
    }

    private func buildDebugContext(signingInput: String) -> String {
        // Only include non-sensitive metadata for debugging
        return "input_len=\(signingInput.count),ts=\(Int(Date().timeIntervalSince1970))"
    }

    private func computeHMAC(data: Data, key: Data) -> Data {
        var hmac = [UInt8](repeating: 0, count: 32)
        data.withUnsafeBytes { dataBytes in
            key.withUnsafeBytes { keyBytes in
                CCHmac(CCHmacAlgorithm(kCCHmacAlgSHA256),
                       keyBytes.baseAddress, key.count,
                       dataBytes.baseAddress, data.count,
                       &hmac)
            }
        }
        return Data(hmac)
    }

    private func constantTimeCompare(_ a: Data, _ b: Data) -> Bool {
        guard a.count == b.count else { return false }
        var result: UInt8 = 0
        for i in 0..<a.count {
            result |= a[i] ^ b[i]
        }
        return result == 0
    }

    private func decodePayload(_ payload: String) -> (subject: String?, scopes: [String]) {
        guard let data = Data(base64Encoded: payload),
              let json = try? JSONSerialization.jsonObject(with: data) as? [String: Any] else {
            return (nil, [])
        }
        let subject = json["sub"] as? String
        let scopes = json["scopes"] as? [String] ?? []
        return (subject, scopes)
    }
}

// MARK: - Request Handler
final class MicroserviceHandler: ChannelInboundHandler {
    typealias InboundIn = HTTPServerRequestPart
    typealias OutboundOut = HTTPServerResponsePart

    private let tokenService: TokenService

    init(tokenService: TokenService) {
        self.tokenService = tokenService
    }

    func channelRead(context: ChannelHandlerContext, data: NIOAny) {
        let part = unwrapInboundIn(data)
        guard case .head(let request) = part else { return }

        let authHeader = request.headers.first(name: "Authorization") ?? ""
        let token = authHeader.hasPrefix("Bearer ") ? String(authHeader.dropFirst(7)) : ""

        let result = tokenService.validateToken(token)

        let status: HTTPResponseStatus = result.isValid ? .ok : .unauthorized
        let responseHead = HTTPResponseHead(version: request.version, status: status)
        context.write(wrapOutboundOut(.head(responseHead)), promise: nil)
        context.writeAndFlush(wrapOutboundOut(.end(nil)), promise: nil)
    }
}

// MARK: - memset_s equivalent
func memset_s(_ ptr: UnsafeMutablePointer<UInt8>, _ destSize: Int, _ value: Int32, _ count: Int) {
    for i in 0..<min(destSize, count) {
        ptr.advanced(by: i).pointee = UInt8(value)
    }
    // Compiler barrier to prevent optimization
    withExtendedLifetime(ptr) {}
}
